CREATE OR REPLACE FUNCTION public.whatsapp_wake() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.whatsapp_messages WHERE status='pending') THEN PERFORM net.http_post(url:='https://project--f96d0623-3d94-4c29-b904-ecb9c33dfe92.lovable.app/api/public/hooks/whatsapp',headers:=jsonb_build_object('Content-Type','application/json','x-service-token',(SELECT token::text FROM public.service_tokens WHERE name='reminders')),body:='{}'::jsonb); END IF; RETURN NEW; EXCEPTION WHEN OTHERS THEN RETURN NEW; END $$;
CREATE FUNCTION public.whatsapp_settings_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.enabled AND NEW.api_url NOT LIKE 'https://%' THEN RAISE EXCEPTION 'Use HTTPS para proteger a chave e as mensagens.'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.whatsapp_settings_validate() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER whatsapp_settings_validate BEFORE INSERT OR UPDATE ON public.whatsapp_settings FOR EACH ROW EXECUTE FUNCTION public.whatsapp_settings_validate();
CREATE FUNCTION public.whatsapp_enabled() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT enabled FROM public.whatsapp_settings WHERE id),false) $$;
REVOKE ALL ON FUNCTION public.whatsapp_enabled() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.whatsapp_enabled() TO authenticated;
CREATE OR REPLACE FUNCTION public.settle_verified_mp(p_token text,p_payment_id text,p_reference uuid DEFAULT NULL,p_status text DEFAULT 'pending',p_amount_cents integer DEFAULT 0,p_approved_at timestamptz DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.store_order_installments;fee integer;expected integer; BEGIN PERFORM public.whatsapp_authorize(p_token); SELECT * INTO p FROM public.store_order_installments WHERE mp_payment_id=p_payment_id FOR UPDATE; IF p.id IS NULL THEN RETURN 'not_found'; END IF; IF p_reference IS NOT NULL AND p.id<>p_reference THEN RAISE EXCEPTION 'Pagamento não corresponde à parcela'; END IF; IF p_status<>'approved' THEN IF p.mp_status IS DISTINCT FROM 'approved' THEN UPDATE public.store_order_installments SET mp_status=p_status WHERE id=p.id; END IF; RETURN 'pending'; END IF; IF p.paid_at IS NOT NULL THEN UPDATE public.store_order_installments SET mp_status='approved' WHERE id=p.id; RETURN 'already_paid'; END IF; fee:=CASE WHEN p.mp_method='boleto' THEN 349 ELSE 0 END; expected:=greatest(0,p.amount_cents-coalesce(p.paid_amount_cents,0)); IF p_amount_cents-fee<>expected OR expected<=0 THEN RAISE EXCEPTION 'Valor recebido diverge do saldo da parcela'; END IF; UPDATE public.store_order_installments SET mp_status='approved',paid_at=coalesce(p_approved_at,now()),paid_amount_cents=coalesce(p.paid_amount_cents,0)+expected WHERE id=p.id; RETURN 'paid'; END $$;